=== src/main/java/hotel/Hotel.java
     1	package hotel;
     2	
     3	import hotel.messages.ArchiveCopy;
     4	import hotel.messages.BlockInvalidAddress;
     5	import hotel.messages.EmailSender;
     6	import hotel.messages.MessageSender;
     7	import hotel.messages.RedirectToTestInbox;
     8	import hotel.messages.SentMessages;
     9	import hotel.reports.OccupancyReport;
    10	import hotel.reports.RevenueReport;
    11	import hotel.reservations.PriceCalculator;
    12	import hotel.reservations.ReservationService;
    13	import hotel.reservations.ReservationStore;
    14	import hotel.rooms.Rooms;
    15	import hotel.web.HttpApi;
    16	import io.javalin.Javalin;
    17	
    18	/** Puts the inn's pieces together and runs the HTTP server. */
    19	public final class Hotel {
    20	
    21	    private final Javalin server;
    22	
    23	    public Hotel() {
    24	        Rooms rooms = new Rooms();
    25	        ReservationStore store = new ReservationStore();
    26	        SentMessages sentMessages = new SentMessages();
    27	        ReservationService reservations =
    28	                new ReservationService(rooms, store, new PriceCalculator(), messageSender(sentMessages));
    29	        HttpApi api = new HttpApi(
    30	                rooms, reservations, sentMessages, new OccupancyReport(rooms, store), new RevenueReport(store));
    31	        this.server = api.server();
    32	    }
    33	
    34	    /**
    35	     * The rules every message goes through. Outside test mode: block invalid addresses, then send and archive a
    36	     * copy. In test mode (HOTEL_TEST_MODE=true): block invalid addresses, then send to the test inbox.
    37	     */
    38	    private static MessageSender messageSender(SentMessages sentMessages) {
    39	        MessageSender email = new EmailSender(sentMessages);
    40	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
    41	        MessageSender delivery = testMode ? new RedirectToTestInbox(email) : new ArchiveCopy(email);
    42	        return new BlockInvalidAddress(delivery, sentMessages);
    43	    }
    44	
    45	    /** Starts listening; port 0 picks a free port. Returns the port in use. */
    46	    public int start(int port) {
    47	        server.start(port);
    48	        return server.port();
    49	    }
    50	
    51	    public void stop() {
    52	        server.stop();
    53	    }
    54	
    55	    public static void main(String[] args) {
    56	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
    57	        new Hotel().start(port);
    58	    }
    59	}

