    42	        assertEquals(List.of("testes@pousadamarealta.com.br | [TESTE] Oi | SENT"), summary());
    43	        assertEquals("Destinatário original: ana@example.com\ntexto", sentMessages.all().get(0).body());
    44	    }
    45	}

